int height_below(ivec3 v)
{
    ivec4 heights = ivec4(floor(heights(v)));
    int h = min(min(heights.x,heights.y),min(heights.z,heights.w));
    return v.z - h;
}
/*
bool is_above(ivec3 v)
{
    return all(lessThan(ivec4(floor(heights(v))),ivec4(v.z)));
}
*/
int height_above(ivec3 v)
{
    ivec4 heights = ivec4(floor(heights(v)));
    int h = max(max(heights.x,heights.y),max(heights.z,heights.w));
    return v.z - h;
}

vec3 force_normal_up(vec3 n)
{
    return n.z < 0.0 ? -n : +n;
}

vec4 force_normal_up(vec4 q)
{
    return vec4(force_normal_up(q.xyz),q.w);
}

vec4 combine(vec4 a, vec4 b)
{
    if(a.w < b.w) return a;
    return b;
}

vec4 sphere_intersection(vec3 ro, vec3 rd, float ra) // adapted from https://iquilezles.org/articles/intersectors
{
    float b = dot( ro, rd );
    float c = dot( ro, ro ) - ra*ra;
    float h = b*b - c;
    if( h<0.0 ) return vec4(-rd, DIST_MAX); // no intersection
    h = sqrt( h );
    float t = -b-h;
    if(t < 0.0) return vec4(-rd, DIST_MAX); // no intersection
    return vec4(normalize(ro+rd*t), t);
}

vec4 box_intersection(vec3 ro, vec3 rd, vec3 sz) // adapted from https://iquilezles.org/articles/intersectors
{
    vec3 m = 1.0/rd;
    vec3 n = m*ro;
    vec3 k = abs(m)*sz;
    vec3 t1 = -n - k;
    vec3 t2 = -n + k;
    float tN = max(max( t1.x, t1.y), t1.z);
    float tF = min(min( t2.x, t2.y), t2.z);
    if( tN>tF || tF<0.0) return vec4(-rd, DIST_MAX); // no intersection
    vec3 norm = (tN>0.0) ? step(vec3(tN),t1) : // ro ouside the box
                                step(t2,vec3(tF));  // ro inside the box
    norm *= -sign(rd);
    return vec4(norm, tN);
}

vec4 box_intersection_eps(vec3 ro, vec3 rd, vec3 v0, vec3 v1)
{
float eps = 0.001;
    v0 += eps;
    v1 -= eps;
    vec3 center = (v0+v1)/2.0;
    vec3 extent = abs(v1-v0)/2.0;
    return box_intersection(ro-center, rd, extent);
}

vec4 cylinder_intersection(vec3 ro, vec3 rd, vec3 a, vec3 b, float ra) // modified https://iquilezles.org/articles/intersectors
{
    vec3  ba = b  - a;
    vec3  oc = ro - a;
    float baba = dot(ba,ba);
    float bard = dot(ba,rd);
    float baoc = dot(ba,oc);
    float k2 = baba            - bard*bard;
    float k1 = baba*dot(oc,rd) - baoc*bard;
    float k0 = baba*dot(oc,oc) - baoc*baoc - ra*ra*baba;
    float h = k1*k1 - k2*k0;
    if( h<0.0 ) return vec4(-rd, DIST_MAX);//no intersection
    h = sqrt(h);
    float t = (-k1-h)/k2;
    // body
    float y = baoc + t*bard;
    if( y>0.0 && y<baba ) return vec4((oc+t*rd - ba*y/baba)/ra, t);
    // caps
    t = ( ((y<0.0) ? 0.0 : baba) - baoc)/bard;
    if( abs(k1+k2*t)<h )
    {
        return vec4(ba*sign(y)/sqrt(baba), t);
    }
    return vec4(-rd, DIST_MAX); // no intersection
}

vec4 triangle_intersection(vec3 ro, vec3 rd, vec3 v0, vec3 v1, vec3 v2) // modified https://iquilezles.org/articles/intersectors/
{
    vec3 v1v0 = v1 - v0;
    vec3 v2v0 = v2 - v0;
    vec3 rov0 = ro - v0;
    vec3  n = cross( v1v0, v2v0 );
    vec3  q = cross( rov0, rd );
    float d = 1.0/dot( rd, n );
    float u = d*dot( -q, v2v0 );
    float v = d*dot(  q, v1v0 );
    float t = d*dot( -n, rov0 );
    if( u<0.0 || v<0.0 || (u+v)>1.0 ) return vec4(-rd, DIST_MAX);
    return vec4(normalize(n), t);
}

vec4 terrain_approximation_with_tiles(vec3 ro, vec3 rd, ivec3 v) // https://www.shadertoy.com/view/4cBfRR terrain approximation with tiles (jt)
{
    vec2 p = vec2(v);
    ivec2 o00 = ivec2(0,0);
    ivec2 o10 = ivec2(1,0);
    ivec2 o01 = ivec2(0,1);
    ivec2 o11 = ivec2(1,1);
    vec2 o = vec2(o00 + o10 + o01 + o11) / 4.0; // for crisp heightmap
    float h00 = height(v.xy+o00);
    float h10 = height(v.xy+o10);
    float h01 = height(v.xy+o01);
    float h11 = height(v.xy+o11);
    float h = (h00 + h01 + h10 + h11) / 4.0; // for crisp heightmap
    vec3 q00 = vec3(o00,h00);
    vec3 q01 = vec3(o01,h01);
    vec3 q10 = vec3(o10,h10);
    vec3 q11 = vec3(o11,h11);
    vec3 q = vec3(o,h);
    ro.z += float(v.z);
    vec4 result =
        combine
        (
            combine
            (
                triangle_intersection(ro, rd, q00, q01, q),
                triangle_intersection(ro, rd, q01, q11, q)
            ),
            combine
            (
                triangle_intersection(ro, rd, q11, q10, q),
                triangle_intersection(ro, rd, q10, q00, q)
            )
        );
#ifdef SMOOTH_NORMALS
    vec2 dst = (ro+rd*result.w).xy;
    result.xyz =
        normalize
        (
            mix
            (
                mix(height_normal(v.xy+o00),height_normal(v.xy+o10),dst.x),
                mix(height_normal(v.xy+o01),height_normal(v.xy+o11),dst.x),
                dst.y
            )
        );
#else
    //result.xyz = height_normal(p+o);
    result.xyz = force_normal_up(result.xyz);
#endif
    return result;
}

struct result
{
    vec3 normal;
    float dist;
    vec3 color;
};

result combine(result a, result b)
{
    //return a.dist < b.dist ? a : b; // ??? why doesn't this compile ???
    if(a.dist < b.dist)
        return a;
    return b;
}

float checker(vec2 p)
{
    return step(0.0,sin(p.x*tau)*sin(p.y*tau));
}

float checker(vec3 p)
{
    return step(0.0,sin(p.x*tau)*sin(p.y*tau)*sin(p.z*tau));
}

result trace(vec3 ray_pos, vec3 ray_dir)
{
    result content = result(-ray_dir, DIST_MAX, vec3(0)); // sky sphere

    // initialization from https://www.shadertoy.com/view/4dX3zl Branchless Voxel Raycasting by fb39ca4 implementing https://lodev.org/cgtutor/raycasting.html
    ivec3 tile = ivec3(floor(ray_pos));
    // decompose ray direction into reciprocal absolute ray direction and sign (-1,+1)
    vec3 delta_dist = 1.0 / abs(ray_dir); // reciprocal absolute ray direction
    ivec3 ray_step = ivec3(sign(ray_dir)); // sign of ray direction
    // initial distances to nearest walls by dimension:
    //     calculate ray position in relation to tile origin
    //     (requires adding one half because tile origin is floor of ray position)
    //     adjust sign according to ray direction
    //     because tile has size 1 and we start in the middle wall is located at 0.5 (sign depends on ray direction)
    //     divide by ray direction (to get distance with respect to ray)
    vec3 side_dist = (sign(ray_dir) * (vec3(tile) - ray_pos) + (sign(ray_dir) * 0.5) + 0.5) * delta_dist; // initial distances to nearest walls by dimension
    bvec3 nearest = bvec3(0); // component is true if nearest wall in that dimension
    for (int i = 0; i < MAX_RAY_STEPS; i++)
    {
        float tmin = length(vec3(nearest) * (side_dist - delta_dist)); // calculate distance to intersection point assuming ray_dir normalized

        // core from https://www.shadertoy.com/view/4dX3zl Branchless Voxel Raycasting by fb39ca4 implementing https://lodev.org/cgtutor/raycasting.html
        bvec3 nearest_next = lessThanEqual(side_dist.xyz, min(side_dist.yzx, side_dist.zxy)); // component is true if nearest wall in that dimension
        vec3 side_dist_next = side_dist + vec3(nearest_next) * delta_dist; // update distances to nearest walls by dimension
        ivec3 tile_next = tile + ivec3(vec3(nearest_next)) * ray_step; // step to next tile in direction of nearest wall
        float tmax = length(vec3(nearest_next) * (side_dist_next - delta_dist)); // calculate distance to intersection point assuming ray_dir normalized

        if(all(lessThan(abs(tile), ivec3(10))))
        {
            vec3 local = ray_pos - vec3(tile);
#ifdef WATER
            float water_level = 0.5;
            if(tile.z == int(floor(water_level)))
            {
                float t = (water_level - ray_pos.z)/ray_dir.z;
                vec3 n = vec3(0,0,1);

                if(t > tmin && t < tmax)
                {
                    vec3 dst = local+ray_dir*t;
                    vec3 color = vec3(0,0,1);
                    content = combine(content, result(n, t, color));
                }
            }
#endif
            int h0 = height_below(tile);
            int h1 = height_above(tile);
            if(h1 > 0)
            {
                if(false)//if(h1 == 1)
                {
                    vec4 q = sphere_intersection(local - 0.5, ray_dir, 0.1);
                    //vec4 q = box_intersection(local - 0.5, ray_dir, vec3(0.49));
                    if(q.w > tmin && q.w < tmax)
                    {
                        content = combine(content, result(q.xyz, q.w, vec3(1,1,1)));
                    }
                }
            }
            else if(h0 < 0)
            {
                if(false)
                {
                    //vec4 q = sphere_intersection(local - 0.5, ray_dir, 0.5);
                    vec4 q = box_intersection(local - 0.5, ray_dir, vec3(0.5 - 0.001));
                    if(q.w > tmin && q.w < tmax)
                    {
                        vec3 dst = local+ray_dir*q.w;
                        vec3 color = mix(vec3(0.5),vec3(0.75),vec3(checker(dst)));
                        content = combine(content, result(q.xyz, q.w, color));
                    }
                }
            }
            else // height_equal
            {
                vec4 q = terrain_approximation_with_tiles(local, ray_dir, tile);
                if(q.w > tmin && q.w < tmax)
                {
                    //vec3 color = vec3(0,1,0);
                    vec3 color = mix(vec3(0.2,0.1,0),vec3(0.15,0.5,0),pow(abs(q.z),2.0));
                    //vec3 color = vec3((local+ray_dir*q.w).xy,0);
                    //vec3 color = vec3(local+ray_dir*q.w);
                    vec3 dst = local+ray_dir*q.w;
                    //color = mix(vec3(0,1,0.1),vec3(0.4,1,0),vec3(hash33(dst*123.0)));
                    //color *= mix(vec3(0.5),vec3(0.75),vec3(checker(dst.xy)));
                    content = combine(content, result(q.xyz, q.w, color));
                }

                float rnd = hash12(vec2(tile.xy));
                if(rnd < 0.1)
                {
                    vec4 q = box_intersection_eps(local, ray_dir, vec3(0.0), vec3(0.1,1,1));
                    if(q.w > tmin && q.w < tmax)
                    {
                        vec3 color = vec3(mix(0.2,0.8,hash13(vec3(tile))));
                        content = combine(content, result(q.xyz, q.w, color));
                    }
                }
                else if(rnd < 0.2)
                {
                    vec4 q = box_intersection_eps(local, ray_dir, vec3(0.0), vec3(1,0.1,1));
                    if(q.w > tmin && q.w < tmax)
                    {
                        vec3 color = vec3(mix(0.2,0.8,hash13(vec3(tile))));
                        content = combine(content, result(q.xyz, q.w, color));
                    }
                }
                else if(rnd < 0.3)
                {
                    vec4 q = box_intersection_eps(local, ray_dir, vec3(0.0), vec3(1,1,0.1));
                    if(q.w > tmin && q.w < tmax)
                    {
                        vec3 color = vec3(mix(0.2,0.8,hash13(vec3(tile))));
                        content = combine(content, result(q.xyz, q.w, color));
                    }
                }
                else if(rnd < 0.4)
                {
                    vec4 q = cylinder_intersection(local, ray_dir, vec3(0.0+0.001,0.5,0.5), vec3(1.0-0.001,0.5,0.5), 0.5);
                    if(q.w > tmin && q.w < tmax)
                    {
                        vec3 color = vec3(mix(0.2,0.8,hash13(vec3(tile))));
                        content = combine(content, result(q.xyz, q.w, color));
                    }
                }
                else if(rnd < 0.5)
                {
                    vec4 q = cylinder_intersection(local, ray_dir, vec3(0.5,0.0+0.001,0.5), vec3(0.5,1.0-0.001,0.5), 0.5);
                    if(q.w > tmin && q.w < tmax)
                    {
                        vec3 color = vec3(mix(0.2,0.8,hash13(vec3(tile))));
                        content = combine(content, result(q.xyz, q.w, color));
                    }
                }
                else if(rnd < 0.6)
                {
                    vec4 q = cylinder_intersection(local, ray_dir, vec3(0.5,0.5,0.0+0.001), vec3(0.5,0.5,1.0-0.001), 0.5);
                    if(q.w > tmin && q.w < tmax)
                    {
                        vec3 color = vec3(mix(0.2,0.8,hash13(vec3(tile))));
                        content = combine(content, result(q.xyz, q.w, color));
                    }
                }
            }

            if(tmin > 0.0) // XXX workaround because first step at 0 instead of at prism wall XXX
            {
            }
        }

        if(content.dist < tmax)
            return content;

        // update state
        nearest = nearest_next;
        tile = tile_next;
        side_dist = side_dist_next;
    }

    return content;
}

void mainImage( out vec4 fragColor, in vec2 I )
{
    bool demo = all(lessThan(iMouse.xy, vec2(10.0)));
    vec2 R = iResolution.xy;
    I = (I + I - R) / R.y; // concise pixel-position mapping thanks to Fabrice
    float yaw = 2.0 * pi * float(iMouse.x) / float(R.x);
    //float pitch = pi - pi / 2.0 * float(iMouse.y) / float(R.y);
    float pitch = pi - pi * float(iMouse.y) / float(R.y);
    yaw = !demo ? yaw : 2.0 * pi * fract(iTime * 0.01);
    pitch = !demo ? pitch : 1.4 * pi/2.0; // circle flight demo
    //pitch = !demo ? pitch : pi/2.0; // hover camera demo

    vec3 ray_pos = vec3(0.0, 0.0, -15.0);
    vec3 ray_dir = vec3(I.x, I.y, 2.0);
    ray_dir = normalize(ray_dir);

    mat3 M = yaw_pitch_roll(yaw, pitch, 0.0);
    ray_pos = M * ray_pos;
    ray_dir = M * ray_dir;
    ray_pos.z += 2.0;

    result res = trace(ray_pos, ray_dir);
    vec3 color = res.color;

    vec3 skycolor = mix(vec3(0.2,0.4,0.8),vec3(0,0,1),abs(ray_dir.z));

    if(res.dist < DIST_MAX)
    {
        res.normal *= dot(res.normal, ray_dir) < 0.0 ? +1.0 : -1.0; // repair front-back for thin surfaces

        vec3 dst = ray_pos + ray_dir * res.dist;
        vec3 light_dir = vec3(0);
        float light = 0.0;
        if(false) // directional light
        {
            light = 2.0;
            light_dir = normalize(vec3(1,2,2));
#ifdef USE_SHADOWS
            light *= trace(dst+res.normal*0.001, light_dir).dist < DIST_MAX ? 0.0 : 1.0;
#endif
        }
        else // point light
        {
            vec3 light_pos = vec3(0);
            if(false)
            {
                light = 400.0;
                light_pos = vec3(20.0*vec2(cos(iTime/5.0),sin(iTime/5.0)),20);
            }
            if(true)
            {
                light = 100.0;
                light_pos = vec3(5.0*vec2(cos(iTime/5.0),sin(iTime/5.0)),10);
            }
            //vec3 light_pos = vec3(0,0,5);
            vec3 light_diff = light_pos - dst;
            float light_dist = length(light_diff);
            light_dir = light_diff / light_dist;
#ifdef USE_SHADOWS
            light *= trace(dst+light_dir*light_dist, -light_dir).dist < light_dist - .001 ? 0.0 : 1.0 / (light_dist * light_dist); // suggested by pyblob to avoid artifacts (missing shadows)
#endif
        }

        float brightness = light * max(0.0, dot(res.normal, light_dir));
        vec3 diffuse = vec3(brightness);
        float ambient = 0.01;

        //color *= (0.5 + 0.5 * result.xyz); // visualize normals
        color *= (diffuse + ambient); // apply light
        //color = vec3(fract(result.w));
#ifdef SPECULAR
        if(brightness > 0.0)
        {
            float specular = pow(max(0.0, dot(res.normal, normalize(-ray_dir + light_dir))), 250.0);
            color += specular;
        }
#endif
        color = mix(skycolor, color, exp(-pow(distance(ray_pos.xy,dst.xy)/50.0, 2.0))); // distance fog (but not vertically)
    }
    else // sky
    {
        color = skycolor;
    }
    color = tanh(color); // roll-off / soft-clamp overly bright colors
    color = sqrt(color); // approximate gamma
    fragColor = vec4(color, 1.0);
}
